mapper.select:
SELECT , goods_category.name AS categoryName, goods_brand.name AS brandName FROM goods_spu AS goods_spu LEFT JOIN goods_category AS goods_category ON goods_spu.category_second_id = goods_category.id LEFT JOIN goods_brand AS goods_brand ON goods_spu.brand_id = goods_brand.id
AND goods_spu.`del_flag` = '0'
AND LOWER(goods_spu.`name`) LIKE CONCAT('%',LOWER(#{query.name}),'%')
AND goods_spu.`status` = #{query.status}
AND goods_category.`id` = #{query.categorySecondId}
AND goods_spu.brand_id = #{query.brandId}

SELECT , goods_category.name AS categoryName, goods_brand.name AS brandName FROM goods_spu AS goods_spu LEFT JOIN goods_category AS goods_category ON goods_spu.category_second_id = goods_category.id LEFT JOIN goods_brand AS goods_brand ON goods_spu.brand_id = goods_brand.id
AND goods_spu.`del_flag` = '0'
AND LOWER(goods_spu.`name`) LIKE CONCAT('%',LOWER(#{query.name}),'%')
AND goods_spu.`status` = #{query.status}
AND goods_spu.brand_id = #{query.brandId}
AND goods_spu.category_first_id = #{query.categoryFirstId}
AND goods_spu.category_second_id = #{query.categorySecondId}

SELECT , goods_category.name AS categoryName, goods_brand.name AS brandName FROM goods_spu AS goods_spu LEFT JOIN goods_category AS goods_category ON goods_spu.category_second_id = goods_category.id LEFT JOIN goods_brand AS goods_brand ON goods_spu.brand_id = goods_brand.id
AND goods_spu.`del_flag` = '0' AND goods_category.`del_flag` = '0' AND goods_spu.`status` = '1'
AND LOWER(goods_spu.`name`) LIKE CONCAT('%',LOWER(#{query.name}),'%')
AND goods_spu.`category_first_id` = #{query.categoryFirstId}
AND goods_spu.`category_second_id` = #{query.categorySecondId}
AND goods_spu.brand_id = #{query.brandId}
AND goods_spu.original_price IS NOT NULL AND goods_spu.original_price > 0 AND goods_spu.original_price >= goods_spu.sales_price * #{bargainRate}
ORDER BY ((goods_spu.original_price - goods_spu.sales_price) / goods_spu.original_price) DESC, goods_spu.sales_price ASC, goods_spu.id DESC
